    + "\n"
    + "honor Num<BigInt> =\n"
    + "    (** The sum of `left` and `right`, exactly. *)\n"
    + "    add(left, right) = nativeAdd(left, right)\n"
    + "    (** The product of `left` and `right`, exactly. *)\n"
    + "    multiply(left, right) = nativeMultiply(left, right)\n"
