    + "        zero, where JS would answer `NaN`. *)\n"
    + "    rem(left, right) =\n"
    + "        if right == 0 then\n"
    + "            throw(DivideByZeroError(\"Int.rem: divisor is zero\"))\n"
    + "        else\n"
    + "            nativeRem(left, right)\n"
    + "\n"
    + "    (** The Euclidean remainder of `left` divided by `right`: always\n"
    + "        non-negative, whatever the signs. Raises `DivideByZeroError` when\n"
    + "        `right` is zero. *)\n"
    + "    mod(left, right) =\n"
    + "        if right == 0 then\n"
    + "            throw(DivideByZeroError(\"Int.mod: divisor is zero\"))\n"
    + "        else\n"
    + "            let remainder = rem(left, right)\n"
    + "            if remainder < 0 then\n"
    + "                remainder + (if right < 0 then -right else right)\n"
    + "            else\n"
    + "                remainder\n"
    + "\n"
    + "    (** The Euclidean quotient of `left` divided by `right`: the unique partner\n"
